1→import test from 'node:test';
2→import assert from 'node:assert/strict';
3→import { execFileSync } from 'node:child_process';
4→import { existsSync, mkdtempSync, readFileSync, writeFileSync } from 'node:fs';
5→import { join } from 'node:path';
6→import { tmpdir } from 'node:os';
7→import { createBrief, createDriver, MockAdapter, MergirafResolver } from '../src/index.mjs';
8→
9→const git = (args, cwd) => execFileSync('git', args, { cwd, encoding: 'utf8' }).trim();
10→const write = (root, path, body) => { const file = join(root, path); execFileSync('mkdir', ['-p', join(file, '..')]); writeFileSync(file, body); };
11→const commit = (root, message) => { git(['add', '-A'], root); git(['commit', '-q', '-m', message], root); return git(['rev-parse', 'HEAD'], root); };
12→const until = async (fn, timeout = 5000) => { const end = Date.now() + timeout; while (Date.now() < end) { const value = await fn(); if (value) return value; await new Promise((r) => setTimeout(r, 10)); } throw new Error('timeout'); };
13→
14→function repo() {
15→  const root = mkdtempSync(join(tmpdir(), 'baton-sm-repo-'));
16→  git(['init', '-q', '-b', 'main'], root); git(['config', 'user.email', 'test@example.com'], root); git(['config', 'user.name', 'Test'], root);
17→  write(root, 'src/value.js', 'export const values = { alpha: 1 };\n'); commit(root, 'base'); return root;
18→}
19→
20→function brief() {
21→  return createBrief({ goal: 'change value', constraints: [], pathScope: ['src/value.js'], definitionOfDone: 'value module remains valid', verification: { command: 'node src/value.js', expectExit: 0 }, budget: { tokens: 1000, usd: 1, wallMin: 1 } });
22→}
23→
24→async function accepted(root, taskId, workerSource, structuredMerge) {
25→  const adapter = new MockAdapter({ scenario: { outcome: 'completed', edits: [{ path: 'src/value.js', content: workerSource }] } });
26→  const logDir = mkdtempSync(join(tmpdir(), 'baton-sm-log-'));
27→  const driver = createDriver({ repoRoot: root, logDir, adapters: { mock: adapter }, structuredMerge, watchdog: { stallMs: 0 } });
28→  const handle = await driver.coordinator.spawn('mock', brief(), { taskId });
29→  await until(async () => (await driver.coordinator.result(handle.id)).ready);
30→  assert.equal((await driver.coordinator.result(handle.id)).status, 'completed');
31→  return { ...driver, handle, logDir };
32→}
33→
34→test('SM1/SM2: missing resolver refuses a conflict without mutating main', async () => {
35→  const root = repo(); const { coordinator, handle } = await accepted(root, 'sm-missing', 'export const values = { alpha: 2 };\n', null);
36→  write(root, 'src/value.js', 'export const values = { alpha: 3 };\n'); commit(root, 'main diverges');
37→  const before = git(['rev-parse', 'HEAD'], root); const status = git(['status', '--porcelain'], root);
38→  await assert.rejects(coordinator.integrate(handle.id, { strategy: 'structured' }), (error) => error.code === 'structured_tool_unavailable');
39→  assert.equal(git(['rev-parse', 'HEAD'], root), before); assert.equal(git(['status', '--porcelain'], root), status);
40→  assert.equal((await coordinator.result(handle.id)).retainedResultRef?.startsWith('refs/baton/results/'), true);
41→});
42→
43→test('SM4: resolver success with conflict markers still refuses and reaps the stage', async () => {
44→  const root = repo();
45→  const resolver = { maxFileBytes: 4096, identity: () => ({ tool: 'fake-mergiraf', version: 'test' }), resolve: async () => ({ status: 'resolved' }) };
46→  const { coordinator, handle } = await accepted(root, 'sm-markers', 'export const values = { alpha: 2 };\n', resolver);
47→  write(root, 'src/value.js', 'export const values = { alpha: 3 };\n'); commit(root, 'main diverges'); const before = git(['rev-parse', 'HEAD'], root);
48→  await assert.rejects(coordinator.integrate(handle.id, { strategy: 'structured' }), (error) => error.code === 'structured_unresolved');
49→  assert.equal(git(['rev-parse', 'HEAD'], root), before);
50→  assert.equal(existsSync(join(root, '.baton', 'integrate')), false);
51→});
52→
53→test('SM6: clean structured resolution is freshly verified before main moves', async () => {
54→  const root = repo(); let calls = 0; let isolatedCwd = null;
55→  const resolver = {
56→    maxFileBytes: 4096,
57→    identity: () => ({ tool: 'fake-mergiraf', version: 'test' }),
58→    resolve: async ({ cwd, relativePath, absolutePath }) => { calls += 1; isolatedCwd = cwd; assert.equal(relativePath, 'value.js'); writeFileSync(absolutePath, 'export const values = { alpha: 2, beta: 3 };\n'); return { status: 'resolved' }; },
59→  };
60→  const { coordinator, log, handle } = await accepted(root, 'sm-success', 'export const values = { alpha: 2 };\n', resolver);
61→  write(root, 'src/value.js', 'export const values = { alpha: 1, beta: 3 };\n'); commit(root, 'main adds beta'); const before = git(['rev-parse', 'HEAD'], root);
62→  const result = await coordinator.integrate(handle.id, { strategy: 'structured', actor: 'test' });
63→  assert.equal(calls, 1); assert.equal(result.integration.beforeSha, before); assert.equal(result.integration.afterSha, git(['rev-parse', 'HEAD'], root));
64→  assert.equal(isolatedCwd.includes('baton-structured-conflict-'), true); assert.equal(isolatedCwd.startsWith(root), false);
65→  assert.equal(result.integration.stageSha, result.integration.afterSha); assert.equal(result.integration.strategy, 'structured');
66→  assert.equal(result.integration.verdict.reverified, true); assert.equal(result.integration.verdict.passed, true);
67→  assert.equal(readFileSync(join(root, 'src/value.js'), 'utf8'), 'export const values = { alpha: 2, beta: 3 };\n');
68→  assert.equal(log.read(handle.id).some((event) => event.kind === 'integration.merge_reverified'), true);
69→  assert.equal(existsSync(join(root, '.baton', 'integrate')), false);
70→});
71→
72→test('SM3-SM7: a clean divergent three-way merge needs no resolver but still gets verified', async () => {
73→  const root = repo(); const { coordinator, handle } = await accepted(root, 'sm-clean-three-way', 'export const values = { alpha: 2 };\n', null);
74→  write(root, 'src/main-only.js', 'export const beta = 3;\n'); commit(root, 'main adds another file');
75→  const result = await coordinator.integrate(handle.id, { strategy: 'structured' });
76→  assert.equal(result.integration.classes.some((item) => item.class === 'clean_textual'), true);
77→  assert.equal(result.integration.resolver, null); assert.equal(result.integration.verdict.passed, true);
78→  assert.equal(readFileSync(join(root, 'src/value.js'), 'utf8'), 'export const values = { alpha: 2 };\n');
79→  assert.equal(readFileSync(join(root, 'src/main-only.js'), 'utf8'), 'export const beta = 3;\n');
80→});
81→
82→test('SM2: a dirty main refuses without changing its bytes or index state', async () => {
83→  const root = repo(); const { coordinator, handle } = await accepted(root, 'sm-dirty', 'export const values = { alpha: 2 };\n', null);
84→  writeFileSync(join(root, 'src/value.js'), 'uncommitted user bytes\n'); const before = git(['rev-parse', 'HEAD'], root); const status = git(['status', '--porcelain=v1'], root);
